from pathlib import Path
import re
p=Path('FactionLedgerIQ.user.js')
s=p.read_text()
s=s.replace('// @version      1.2.12','// @version      1.2.13',1)
s=s.replace("const VERSION='1.2.12';","const VERSION='1.2.13';",1)
s=s.replace("settings:{playerName:'',playerId:'',factionName:'',apiKey:'',apiPolling:true,apiPollSeconds:15,displayTracking:false,showAllFactionItems:false},","settings:{playerName:'',playerId:'',factionName:'',apiKey:'',apiPolling:true,apiPollSeconds:15,displayTracking:false,showAllFactionItems:false,displayTrackedItems:[]},",1)

display_block=r'''function manualDisplayItem(id){id=String(id||'');const a=Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[];return a.find(x=>String(x&&x.itemId||'')===id)||null;}
function displayRelevant(id){id=String(id||'');if(!id)return false;if(whitelist(id,itemName(id))||manualDisplayItem(id))return true;return activeLots().some(l=>String(l.itemId)===id&&l.owner===F&&(l.location===INV||l.location===DISP));}
function moveToFactionDisplay(id,qty,opts={}){id=String(id);qty=Math.max(1,Number(qty||1));const managed=!!whitelist(id,itemName(id))||!!manualDisplayItem(id),fAvail=balance(id,F,INV),pAvail=managed?balance(id,P,INV):0,fq=Math.min(qty,fAvail),pq=Math.min(qty-fq,pAvail),moved=fq+pq;if(!moved)throw new Error(managed?'No tracked stock available to move to Display':'Only faction-owned stock can be tracked in Display');if(moved<qty&&!managed)throw new Error('Only faction-owned stock can be tracked in Display');const m={id:uid('MOV'),type:'DISPLAY_IN',itemId:id,itemName:itemName(id),qty:moved,from:INV,to:DISP,timestamp:opts.timestamp||new Date().toISOString(),apiVerified:opts.apiVerified===true,apiLogIds:[],mvEachFrozen:mv(id),allocations:[],claimIds:[],receiptBatchId:'',status:'ACTIVE',verificationSource:opts.verificationSource||'',displayReconcileMode:opts.displayReconcileMode||'',notes:managed?'Managed item moved to Display; Display Case ownership is Faction.':'Faction-owned item moved to Display.'},fr=consume(id,F,INV,fq,m.id),pr=consume(id,P,INV,pq,m.id);m.allocations=fr.allocations.concat(pr.allocations);state.movements.push(m);m.allocations.forEach(a=>addLot({itemId:id,itemName:m.itemName,owner:F,location:DISP,qty:a.qty,sourceType:a.owner===P?'MANAGED_DISPLAY_TRANSFER':'LOCATION_TRANSFER',sourceRef:m.id,rootId:a.rootId,costBasisKnown:a.costBasisKnown,costEach:a.costEach,mvAtSource:a.mvAtSource,notes:a.owner===P?'Managed stock becomes faction-owned while in Display Case.':'Faction-owned stock moved to Display Case.'}));return m;}
function moveFromFactionDisplay(id,qty,opts={}){id=String(id);qty=Math.max(1,Number(qty||1));if(qty>balance(id,F,DISP))throw new Error('Not enough tracked faction-owned Display stock');const m={id:uid('MOV'),type:'DISPLAY_OUT',itemId:id,itemName:itemName(id),qty,from:DISP,to:INV,timestamp:opts.timestamp||new Date().toISOString(),apiVerified:opts.apiVerified===true,apiLogIds:[],mvEachFrozen:mv(id),allocations:[],claimIds:[],receiptBatchId:'',status:'ACTIVE',verificationSource:opts.verificationSource||'',displayReconcileMode:opts.displayReconcileMode||'',notes:'Faction-owned Display stock moved back to Personal Inventory location.'},fr=consume(id,F,DISP,qty,m.id);m.allocations=fr.allocations;state.movements.push(m);m.allocations.forEach(a=>addLot({itemId:id,itemName:m.itemName,owner:F,location:INV,qty:a.qty,sourceType:'LOCATION_TRANSFER',sourceRef:m.id,rootId:a.rootId,costBasisKnown:a.costBasisKnown,costEach:a.costEach,mvAtSource:a.mvAtSource,notes:'Faction-owned stock returned from Display Case.'}));return m;}
function displayCountsFromApi(payload){const raw=payload&&payload.display!==undefined?payload.display:[],out={};for(const e of (Array.isArray(raw)?raw:Object.values(raw||{}))){const id=String(e?(e.ID??e.id??''):'').trim(),q=Number(e?(e.quantity??e.amount??0):0);if(id&&q>0)out[id]=(out[id]||0)+q;}return out;}
function displaySnapshotState(){if(!state.displaySnapshot||typeof state.displaySnapshot!=='object')state.displaySnapshot={counts:{},initializedAt:'',updatedAt:'',rulesVersion:0};if(!state.displaySnapshot.counts||typeof state.displaySnapshot.counts!=='object')state.displaySnapshot.counts={};return state.displaySnapshot;}
function migrateLegacyDisplaySnapshot(){const rows=state.movements.filter(m=>m&&m.status!=='VOID'&&m.verificationSource==='DISPLAY_SNAPSHOT'&&m.displayReconcileMode!=='DELTA'&&!m.receiptBatchId).slice().sort((a,b)=>new Date(b.timestamp||0)-new Date(a.timestamp||0));let changed=false;for(const m of rows){const dest=String(m.to||''),src=String(m.from||''),lots=state.lots.filter(l=>l&&l.status==='OPEN'&&String(l.sourceRef||'')===String(m.id)&&String(l.location||'')===dest&&Number(l.qtyRemaining||0)>0),qty=lots.reduce((n,l)=>n+Number(l.qtyRemaining||0),0);if(qty!==Number(m.qty||0))continue;for(const l of lots){const q=Number(l.qtyRemaining||0);l.qtyRemaining=0;l.status='VOID';l.voidedAt=new Date().toISOString();l.voidReason='Legacy Display snapshot correction';addLot({itemId:l.itemId,itemName:l.itemName,owner:l.owner,location:src,qty:q,sourceType:'DISPLAY_BASELINE_CORRECTION',sourceRef:m.id,rootId:l.rootId,costBasisKnown:l.costBasisKnown,costEach:l.costEach,mvAtSource:l.mvAtSource,notes:'Returned to prior LedgerIQ location because pre-existing Display Case stock was incorrectly treated as a new movement.'});}m.status='VOID';m.voidedAt=new Date().toISOString();m.voidReason='Legacy Display snapshot reconciliation treated pre-existing Display Case stock as a new movement';changed=true;}if(changed)state.displaySnapshot={counts:{},initializedAt:'',updatedAt:'',rulesVersion:0};return changed;}
function convertManagedPersonalDisplay(){let changed=false,now=new Date().toISOString();for(const l of activeLots().filter(x=>x.owner===P&&x.location===DISP&&(whitelist(x.itemId,x.itemName)||manualDisplayItem(x.itemId)))){const q=Number(l.qtyRemaining||0);if(!q)continue;l.qtyRemaining=0;l.status='VOID';l.voidedAt=now;l.voidReason='Display rule update: managed Display Case stock is faction-owned';addLot({itemId:l.itemId,itemName:l.itemName,owner:F,location:DISP,qty:q,sourceType:'DISPLAY_RULE_CONVERSION',sourceRef:l.id,rootId:l.rootId,costBasisKnown:l.costBasisKnown,costEach:l.costEach,mvAtSource:l.mvAtSource,notes:'Managed Display Case stock classified as faction-owned.'});changed=true;}return changed;}
function seedDisplayRules(actual){const snap=displaySnapshotState(),now=new Date().toISOString();let changed=convertManagedPersonalDisplay(),managed=new Map();for(const w of state.whitelist||[])if(w&&w.itemId)managed.set(String(w.itemId),w.itemName||itemName(w.itemId));for(const x of (Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[]))if(x&&x.itemId)managed.set(String(x.itemId),x.itemName||itemName(x.itemId));for(const [id,name] of managed){const physical=Math.max(0,Number(actual[id]||0)),tracked=Math.max(0,balance(id,F,DISP));if(physical>tracked){addLot({itemId:id,itemName:name,owner:F,location:DISP,qty:physical-tracked,sourceType:'DISPLAY_BASELINE',sourceRef:'',costBasisKnown:false,mvAtSource:mv(id),createdAt:now,notes:'Managed item already present in Display Case when faction-display tracking baseline was established.'});changed=true;}}const relevant={};for(const id of new Set([...managed.keys(),...activeLots().filter(l=>l.owner===F&&(l.location===INV||l.location===DISP)).map(l=>String(l.itemId))]))if(id)relevant[id]=Math.max(0,Number(actual[id]||0));snap.counts=relevant;snap.initializedAt=snap.initializedAt||now;snap.updatedAt=now;snap.rulesVersion=3;return changed;}
async function reconcileDisplayCase(){if(!state.settings.displayTracking||!apiKey())return false;const payload=await apiFetch('user',{selections:'display'}),actual=displayCountsFromApi(payload),snap=displaySnapshotState(),now=new Date().toISOString();if(Number(snap.rulesVersion||0)!==3)return seedDisplayRules(actual);const managedIds=[...(state.whitelist||[]).map(w=>String(w&&w.itemId||'')),...(Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[]).map(x=>String(x&&x.itemId||''))].filter(Boolean),relevantIds=new Set([...managedIds,...activeLots().filter(l=>l.owner===F&&(l.location===INV||l.location===DISP)).map(l=>String(l.itemId))]),prev=snap.counts||{},next={};let changed=false;for(const id of relevantIds){const physical=Math.max(0,Number(actual[id]||0)),before=Math.max(0,Number(prev[id]||0)),delta=physical-before;next[id]=physical;if(delta>0){const managed=!!whitelist(id,itemName(id))||!!manualDisplayItem(id),fAvail=balance(id,F,INV),pAvail=managed?balance(id,P,INV):0,movable=Math.min(delta,fAvail+pAvail);if(movable>0){const m=moveToFactionDisplay(id,movable,{timestamp:now,apiVerified:true,verificationSource:'DISPLAY_SNAPSHOT',displayReconcileMode:'DELTA'});m.notes=managed?'Managed Display increase reconciled from Torn API; Display ownership is Faction.':'Faction-owned Display increase reconciled from Torn API.';changed=true;}const remainder=delta-movable;if(remainder>0&&managed){addLot({itemId:id,itemName:itemName(id),owner:F,location:DISP,qty:remainder,sourceType:'DISPLAY_MANAGED_INTAKE',sourceRef:'',costBasisKnown:false,mvAtSource:mv(id),createdAt:now,notes:'Managed Display Case increase with no tracked source; classified as faction-owned by Display rule.'});changed=true;}}else if(delta<0){const tracked=Math.max(0,balance(id,F,DISP)),q=Math.min(-delta,tracked);if(q>0){const m=moveFromFactionDisplay(id,q,{timestamp:now,apiVerified:true,verificationSource:'DISPLAY_SNAPSHOT',displayReconcileMode:'DELTA'});m.notes='Faction-owned Display decrease reconciled from Torn API; item is now faction-owned in Personal Inventory location.';changed=true;}}}snap.counts=next;snap.updatedAt=now;return changed;}
function correctExistingDisplaySource(id,qty){id=String(id||'');qty=Math.max(1,Number(qty||1));if(qty>balance(id,P,INV))throw new Error('Not enough tracked personal stock for this correction');if(qty>balance(id,F,DISP))throw new Error('Not enough existing faction Display stock for this correction');const m={id:uid('MOV'),type:'DISPLAY_SOURCE_CORRECTION',itemId:id,itemName:itemName(id),qty,from:INV,to:DISP,timestamp:new Date().toISOString(),apiVerified:false,apiLogIds:[],mvEachFrozen:mv(id),allocations:[],claimIds:[],receiptBatchId:'',status:'ACTIVE',notes:'One-time correction: existing faction Display stock was already counted, so tracked Personal stock was reduced without increasing Display quantity.'},pr=consume(id,P,INV,qty,m.id);if(pr.unresolved)throw new Error('Could not apply Display source correction');m.allocations=pr.allocations;state.movements.push(m);return m;}

function factionPart'''
s,n=re.subn(r"function displayRelevant\(id\).*?function factionPart",display_block,s,flags=re.S)
if n!=1: raise SystemExit(f'display block replace count {n}')

inventory_rows=r'''function inventoryRows(){const map=new Map();activeLots().forEach(l=>{if(!state.settings.displayTracking&&l.location===DISP)return;if(l.location===DISP&&l.owner!==F)return;const k=String(l.itemId);if(!map.has(k))map.set(k,{itemId:k,itemName:l.itemName||itemName(k),personal:0,faction:0,factionDisplay:0,mv:mv(k)});const r=map.get(k);if(l.location===INV&&l.owner===P)r.personal+=Number(l.qtyRemaining||0);if(l.location===INV&&l.owner===F)r.faction+=Number(l.qtyRemaining||0);if(l.location===DISP&&l.owner===F)r.factionDisplay+=Number(l.qtyRemaining||0);});return Array.from(map.values()).sort((a,b)=>a.itemName.localeCompare(b.itemName));}
function movementCard'''
s,n=re.subn(r"function inventoryRows\(\).*?function movementCard",inventory_rows,s,flags=re.S)
if n!=1: raise SystemExit(f'inventoryRows replace count {n}')

inventory_html=r'''function inventoryHtml(){const rows=inventoryRows(),manualDisplay=Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[];return `<div class="fliq-section"><div class="fliq-section-title"><span>Add Current / Opening Stock</span><span class="fliq-muted">Optional</span></div><div class="fliq-muted">Add the personal or faction-owned stock you want LedgerIQ to track. Whitelisting an item by itself does not create an Inventory row.</div><div class="fliq-row fliq-form-row">${itemSearchField('fliq-open-item','Item name or ID')}<input id="fliq-open-qty" class="fliq-input" type="number" min="1" placeholder="Qty"></div><div class="fliq-row fliq-form-row"><select id="fliq-open-owner" class="fliq-select"><option value="PERSONAL">Personally Owned</option><option value="FACTION">Faction Owned</option></select><input id="fliq-open-location" type="hidden" value="PERSONAL_INVENTORY"></div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="add-opening">Add Stock</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Tracked Inventory</span><span class="fliq-muted">${rows.length} item${rows.length===1?'':'s'}</span></div><div class="fliq-inventory-list">${rows.length?rows.map(r=>`<div class="fliq-inventory-card"><div class="fliq-item-top"><div class="fliq-item-name">${esc(r.itemName)}</div><div class="fliq-inventory-mv">${money(r.mv)}<small> current MV</small></div></div><div class="fliq-inventory-stats"><div><span>Personal</span><b>${r.personal.toLocaleString()}</b></div><div><span>Faction</span><b>${r.faction.toLocaleString()}</b></div>${state.settings.displayTracking?`<div><span>Faction Display</span><b>${r.factionDisplay.toLocaleString()}</b></div>`:''}</div></div>`).join(''):'<div class="fliq-muted">No tracked inventory yet.</div>'}</div></div>${state.settings.displayTracking?`<div class="fliq-section"><div class="fliq-section-title"><span>Display Case Tracking</span></div><div class="fliq-muted">Automatic for whitelisted items and faction-owned stock from the Armory. Any Display stock tracked here is faction-owned. Other Display Case items are ignored unless you add them below.</div><div class="fliq-row" style="margin-top:8px">${itemSearchField('fliq-display-track-item','Add non-whitelisted Display item')}<button class="fliq-btn" data-fliq="add-display-track">Track</button></div><div class="fliq-list">${manualDisplay.map(x=>`<div class="fliq-list-item"><div class="fliq-item-top"><div><b>${esc(x.itemName||itemName(x.itemId))}</b><div class="fliq-muted">Faction-owned when present in Display</div></div><button class="fliq-btn fliq-btn-small" data-fliq="remove-display-track" data-id="${esc(x.itemId)}">Remove</button></div></div>`).join('')}</div></div><div class="fliq-section"><div class="fliq-section-title"><span>Existing Display Correction</span><span class="fliq-muted">One-time only</span></div><div class="fliq-muted">Use only when an item was physically moved from Personal Inventory to Display before automatic Display tracking was active. This reduces the tracked Personal count without adding another Display item.</div><div class="fliq-row fliq-form-row">${itemSearchField('fliq-display-correct-item','Item')}<input id="fliq-display-correct-qty" class="fliq-input" type="number" min="1" placeholder="Qty"></div><div class="fliq-actions"><button class="fliq-btn" data-fliq="correct-display-source">Correct Personal → Existing Display</button></div></div>`:''}`;}
function rafflesHtml'''
s,n=re.subn(r"function inventoryHtml\(\).*?function rafflesHtml",inventory_html,s,flags=re.S)
if n!=1: raise SystemExit(f'inventoryHtml replace count {n}')

actions=r'''if(a==='add-opening'){const i=parseItem(document.getElementById('fliq-open-item').value),q=Number(document.getElementById('fliq-open-qty').value||0),owner=document.getElementById('fliq-open-owner').value,loc=INV;if(!i||!Number.isInteger(q)||q<=0){toast('Choose an item and whole quantity');return;}addLot({itemId:i.id,itemName:i.name,owner,location:loc,qty:q,sourceType:'OPENING',costBasisKnown:false,mvAtSource:mv(i.id),notes:'Opening stock entered manually.'});save();toast('Stock added');return;}if(a==='add-display-track'){const i=parseItem(document.getElementById('fliq-display-track-item').value);if(!i||!i.id){toast('Choose an item');return;}if(whitelist(i.id,i.name)){toast('That item is whitelisted and already tracks Display automatically');return;}if(!Array.isArray(state.settings.displayTrackedItems))state.settings.displayTrackedItems=[];if(!state.settings.displayTrackedItems.some(x=>String(x.itemId)===String(i.id)))state.settings.displayTrackedItems.push({itemId:String(i.id),itemName:i.name,addedAt:new Date().toISOString()});save(false);try{await reconcileDisplayCase();save();toast('Display item added and synced');}catch(e){save();toast('Display item added; sync failed: '+String(e&&e.message||e));}return;}if(a==='remove-display-track'){state.settings.displayTrackedItems=(Array.isArray(state.settings.displayTrackedItems)?state.settings.displayTrackedItems:[]).filter(x=>String(x.itemId)!==String(t.dataset.id||''));save();toast('Display tracking rule removed');return;}if(a==='correct-display-source'){const i=parseItem(document.getElementById('fliq-display-correct-item').value),q=Number(document.getElementById('fliq-display-correct-qty').value||0);if(!i||!Number.isInteger(q)||q<=0){toast('Choose an item and whole quantity');return;}try{correctExistingDisplaySource(i.id,q);save();toast('Existing Display source corrected');}catch(e){toast(String(e&&e.message||e));}return;}if(a==='display-in'||a==='display-out'){toast('Display location is now tracked automatically from Torn');return;}if(a==='start-raffle')'''
s,n=re.subn(r"if\(a==='add-opening'\).*?if\(a==='start-raffle'\)",actions,s,flags=re.S)
if n!=1: raise SystemExit(f'action block replace count {n}')

p.write_text(s)
